from pathlib import Path
from typing import TYPE_CHECKING, Optional

if TYPE_CHECKING:
    from .base import ArtifactAdapter
    from .config import SpecConfig

from .base import AdapterError, AdapterAuthError, AdapterOfflineError

# Cache key includes spec id when multi-spec — same project_dir / different spec
# id must yield different adapter instances (different cache paths / filter).
_adapter_cache: dict[str, "ArtifactAdapter"] = {}


def get_adapter(project_dir: Path, spec: Optional["SpecConfig"] = None) -> "ArtifactAdapter":
    """Get the configured adapter for a project directory.

    Returns a cached singleton per (project_dir, spec_id). The adapter type
    is determined by .synaptory.yaml (tracker.backend key). Multi-spec is
    supported by every backend. Remote backends scope by their native
    discriminator; the local backend scopes by filesystem path under
    `.synaptory/.orchestrator/specs/<id>/`.
    """
    spec_id = spec.id if spec is not None else ""
    key = f"{project_dir.resolve()}::{spec_id}"
    if key in _adapter_cache:
        return _adapter_cache[key]

    from .config import TrackerConfig
    config = TrackerConfig.load(project_dir)

    if config.backend == "github":
        from .github_adapter import GitHubAdapter
        adapter = GitHubAdapter(project_dir, config, spec=spec)
    elif config.backend == "jira":
        from .jira_adapter import JiraAdapter
        adapter = JiraAdapter(project_dir, config, spec=spec)
    elif config.backend == "teamwork":
        from .teamwork_adapter import TeamworkAdapter
        adapter = TeamworkAdapter(project_dir, config, spec=spec)
    elif config.backend == "linear":
        from .linear_adapter import LinearAdapter
        adapter = LinearAdapter(project_dir, config, spec=spec)
    elif config.backend == "local":
        # "local" is the default — compact JSON state plus Markdown artifacts.
        from .local_adapter import LocalAdapter
        adapter = LocalAdapter(project_dir, config, spec=spec)
    else:
        raise AdapterError(
            f"Unsupported tracker backend: {config.backend!r}. "
            "Supported backends: local, github, jira, teamwork, linear."
        )

    _adapter_cache[key] = adapter
    return adapter


