def resolve_spec(project_dir: Path, spec_flag: Optional[str] = None) -> Optional["SpecConfig"]:
    """Resolve the active SpecConfig for a CLI invocation.

    Resolution order (design §6.1):
      1. Explicit `--spec=<id>` flag.
      2. `pipeline-state.json.active_spec` (the persisted default).
      3. None — legacy single-spec mode.

    Errors:
      - Raises ValueError when multi-spec is configured but neither the
        flag nor `active_spec` resolves to a known spec.
      - Raises ValueError when an explicit flag points at an unknown spec id.
    """
    from .config import TrackerConfig
    config = TrackerConfig.load(project_dir)
    if not config.is_multispec():
        if spec_flag:
            raise ValueError(
                f"--spec={spec_flag!r} given but no `specs:` block in "
                ".synaptory.yaml — this is a single-spec project."
            )
        return None

    if spec_flag:
        sc = config.find_spec(spec_flag)
        if sc is None:
            raise ValueError(
                f"--spec={spec_flag!r}: unknown spec id. "
                f"Known: {[s.id for s in config.specs]}"
            )
        return sc

    # Fall back to active_spec from pipeline-state.json
    active = _read_active_spec(project_dir)
    if active:
        sc = config.find_spec(active)
        if sc is not None:
            return sc

    raise ValueError(
        "Multi-spec project but no active spec — pass --spec=<id> or set "
        f"pipeline-state.json.active_spec. Known specs: {[s.id for s in config.specs]}"
    )


def _read_active_spec(project_dir: Path) -> Optional[str]:
    import json as _json
    p = project_dir / ".synaptory" / ".orchestrator" / "pipeline-state.json"
    if not p.exists():
        return None
    try:
        state = _json.loads(p.read_text(encoding="utf-8"))
    except (OSError, _json.JSONDecodeError):
        return None
    active = state.get("active_spec")
    return active if isinstance(active, str) and active else None


def clear_cache() -> None:
    """Clear the adapter cache (useful for testing)."""
    _adapter_cache.clear()
